- name: Ensure no security step has continue-on-error: true
  run: |
    set -euo pipefail
    violation=0
    while IFS= read -r f; do
      awk '
        /^- / { if (in_block) check_block(); in_block=1; block=""; next }
        { if (in_block) block = block "\n" $0 }
        END { if (in_block) check_block() }
        function check_block() {
          if (block ~ /name:[[:space:]]*[^\n]*security[^\n]*/i && block ~ /continue-on-error:[[:space:]]*true/) {
            exit 1
          }
        }
      ' "$f" && : || { echo "Violation in $f"; violation=1; }
    done < <(find .github/workflows -type f \( -name "*.yaml" -o -name "*.yml" \) 2>/dev/null)
    if (( violation )); then
      exit 1
    fi
fi
